 app.querySelectorAll('.field').forEach(field=>{const control=field.querySelector('input:not([type="checkbox"]),select,textarea');if(!control||!control.id||control.id.endsWith('-hex'))return;const label=field.querySelector('label,.field-label')?.textContent?.trim()||'';const help=controlHelp(slug,control.id,label);if(!help)return;const note=document.createElement('p');note.className='field-help';note.id=control.id+'-help';note.textContent=help;control.setAttribute('aria-describedby',note.id);field.append(note)});
 // BM: Event input: kendalikan interaksi tanpa mengubah sumber data atau memintas validasi modul.
