 // BM: Event input: kendalikan interaksi tanpa mengubah sumber data atau memintas validasi modul.
 // EN: input event: handle interaction without mutating source data or bypassing module validation.
 app.querySelectorAll('.color-control input[type="color"]').forEach(el=>{const hex=$(el.id+'-hex');el.addEventListener('input',()=>hex.value=el.value.toUpperCase());hex?.addEventListener('change',()=>{const value=hex.value.trim();if(/^#[a-fA-F0-9]{6}$/.test(value))el.value=value;else hex.value=el.value.toUpperCase()})});
