// BM: chosen: Mengasingkan satu langkah operasi supaya boleh disemak dan diuji. Tujuan modul: memasang alat browser mengikut ID, mengurus input dan output setempat, serta mengelakkan muat naik tersirat. Input: id='file'.
// EN: chosen: Isolates one operation so it can be reviewed and tested. Module purpose: mounts browser tools by ID, handles local inputs and outputs, and avoids implicit uploads. Inputs: id='file'.
function chosen(id='file'){const f=$(id)?.files?.[0];if(!f)throw new Error('Choose a file first.');if(f.size>45*1024*1024)throw new Error('File too large (45 MB limit).');return f}
async function imgFile(id='file'){const f=chosen(id);if(!f.type.startsWith('image/'))throw new Error('Choose an image file.');const url=URL.createObjectURL(f);try{const image=new Image();image.src=url;await image.decode();if(image.naturalWidth*image.naturalHeight>30000000)throw new Error('Image exceeds 30 megapixels. Resize before using this tool.');return {file:f,image}}finally{URL.revokeObjectURL(url)}}
const canvas=(w,h)=>{if(w<1||h<1||w*h>32000000)throw new Error('Output dimensions must be positive and at most 32 megapixels.');const c=document.createElement('canvas');c.width=Math.round(w);c.height=Math.round(h);return c};
const renderImage=(c)=>{$('preview').replaceChildren(c)};
const blobOf=(c,type='image/png',quality=.88)=>new Promise((ok,fail)=>c.toBlob(b=>b?ok(b):fail(new Error('Your browser cannot encode the selected image format.')),type,quality));
function download(blob,name){const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000)}
// BM: downloadText: Mengasingkan satu langkah operasi supaya boleh disemak dan diuji. Tujuan modul: memasang alat browser mengikut ID, mengurus input dan output setempat, serta mengelakkan muat naik tersirat. Input: s,name,type='text/plain'.
// EN: downloadText: Isolates one operation so it can be reviewed and tested. Module purpose: mounts browser tools by ID, handles local inputs and outputs, and avoids implicit uploads. Inputs: s,name,type='text/plain'.
const downloadText=(s,name,type='text/plain')=>download(new Blob([s],{type}),name);
