        popup.document.open();popup.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>${xmlEscape(base)} – Print to PDF</title><style>body{font-family:Arial,Helvetica,sans-serif;color:#171c22;max-width:800px;margin:35px auto;padding:0 26px;line-height:1.5}img{max-width:100%}table{border-collapse:collapse;width:100%}td,th{border:1px solid #bbb;padding:7px}h1,h2,h3{line-height:1.25}button{background:#bd5338;color:#fff;border:0;border-radius:9px;padding:12px 16px;cursor:pointer}@media print{.print-bar{display:none}body{margin:0;max-width:none;padding:0}@page{size:A4;margin:16mm}}</style></head><body><div class="print-bar"><p>Review the layout before printing. For a PDF, choose <strong>Save as PDF</strong> as your printer.</p><button onclick="window.print()">Print / Save as PDF</button><hr></div>${parsed.body.innerHTML}</body></html>`);popup.document.close();text('Opened a printable Word preview. Review its layout, then click Print / Save as PDF in the preview window.');return;
