function registerQR(){
  set(`<div class="field-grid">${textarea('Text or URL','qrtext','https://zrain.web.app')}${number('QR image size (px)','size',360,160,800)}${input('QR color','foreground','#121E2A','color')}${input('Background color','background','#FFFFFF','color')}</div>${notice('The QR code is generated on your device without an external library or uploading text. Leave strong contrast for reliable scanning.')}${buttons('Generate QR','Download PNG')}${preview()}${result()}`);
  $('qrtext').value='https://zrain.web.app';let qrCanvas=null;
  onRun(async()=>{const content=v('qrtext').trim();if(!content)throw Error('Enter text or a URL.');if(new TextEncoder().encode(content).length>900)throw Error('QR content too long (900 UTF-8 bytes maximum).');if(contrast(hexToRgb(v('foreground')),hexToRgb(v('background')))<4.5)throw Error('QR and background colors need more contrast to scan.');
    const size=n('size');if(size<160||size>800)throw Error('QR size must be 160–800 px.');qrCanvas=drawQr(content,size,v('foreground'),v('background'));$('preview').replaceChildren(qrCanvas);text('QR generated locally with a four-module quiet zone. Test scanning it before sharing.')});
  // BM: Event click: kendalikan interaksi tanpa mengubah sumber data atau memintas validasi modul.
  // EN: click event: handle interaction without mutating source data or bypassing module validation.
  $('secondary').addEventListener('click',async()=>{if(!qrCanvas)return toast('Generate your QR first.');await outputCanvas(qrCanvas,'zrain-qr.png')});
}

function registerTextTools(){
  set(`<div class="field-grid">${textarea('Input text','source','Paste or type your text here')}${select('Operation','operation',[['upper','UPPERCASE'],['lower','lowercase'],['title','Title Case'],['trim','Trim whitespace and empty lines'],['unique','Remove duplicate lines'],['sort','Sort lines A–Z'],['reverse','Reverse line order'],['count','Count words and characters']])}</div>${buttons('Process text','Download result')}<div class="field" style="margin-top:16px"><label for="textout">Output</label><textarea id="textout" rows="9" class="bigoutput"></textarea></div>${result()}`);
  onRun(()=>{const raw=v('source');let out;switch(v('operation')){case 'upper':out=raw.toUpperCase();break;case 'lower':out=raw.toLowerCase();break;case 'title':out=raw.toLowerCase().replace(/\b\p{L}/gu,c=>c.toUpperCase());break;case 'trim':out=raw.split(/\r?\n/).map(s=>s.trim()).filter(Boolean).join('\n');break;case 'unique':out=[...new Set(raw.split(/\r?\n/))].join('\n');break;case 'sort':out=raw.split(/\r?\n/).sort((a,b)=>a.localeCompare(b)).join('\n');break;case 'reverse':out=raw.split(/\r?\n/).reverse().join('\n');break;default:out=`Words: ${(raw.trim().match(/\S+/g)||[]).length}\nCharacters: ${[...raw].length}\nLines: ${raw.split(/\r?\n/).length}`} $('textout').value=out;text('Text processed.')});
  // BM: Event click: kendalikan interaksi tanpa mengubah sumber data atau memintas validasi modul.
  // EN: click event: handle interaction without mutating source data or bypassing module validation.
  $('secondary').addEventListener('click',()=>downloadText(v('textout'),'zrain-processed-text.txt'));
}
function registerFocus(){
  set(`<div class="field-grid">${number('Focus minutes','focus',25,1,180)}${number('Break minutes','break',5,1,60)}</div><div class="focus-display" aria-live="polite"><p class="eyebrow" id="timerlabel">FOCUS SESSION</p><p id="clock" class="focus-clock">25:00</p><div class="progress-track"><div id="timerprogress" class="progress-fill"></div></div><p class="muted" id="timerstate">Ready to begin</p><p class="muted" id="done">Completed focus sessions: 0</p></div><div class="actions"><button class="btn" id="begin" type="button">Start</button><button class="btn secondary" id="pause" type="button">Pause</button><button class="btn secondary" id="reset" type="button">Reset session</button><button class="btn secondary" id="mode" type="button">Switch to break</button><button class="btn secondary" id="clearstats" type="button">Clear session count</button></div>${notice('Focus and break lengths can be changed while paused. Timers resume using wall-clock time when you return to this browser tab. This is not an alarm service.')}${result()}`);
  const storeKey='zrain-focus-v2';let state={mode:'focus',remaining:25*60000,duration:25*60000,endAt:null,active:false,completed:0,focus:25,break:5};
  try{const saved=JSON.parse(localStorage.getItem(storeKey)||'null');if(saved&&['focus','break'].includes(saved.mode)&&Number.isFinite(saved.remaining)&&saved.remaining>=0){state={...state,...saved};state.active=!!saved.active;state.completed=Math.max(0,Math.floor(Number(saved.completed)||0));state.focus=clamp(Number(saved.focus)||25,1,180);state.break=clamp(Number(saved.break)||5,1,60);$('focus').value=state.focus;$('break').value=state.break;}}catch{}
  // BM: save: Mengubah state yang berkaitan hanya selepas input dan syarat akses diperiksa. Tujuan modul: memasang alat browser mengikut ID, mengurus input dan output setempat, serta mengelakkan muat naik tersirat.
  // EN: save: Mutates relevant state only after input and access conditions are verified. Module purpose: mounts browser tools by ID, handles local inputs and outputs, and avoids implicit uploads.
  const save=()=>{try{localStorage.setItem(storeKey,JSON.stringify(state))}catch{}};
  function update(){const seconds=Math.max(0,Math.ceil(state.remaining/1000));$('clock').textContent=`${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;$('timerlabel').textContent=state.mode==='focus'?'FOCUS SESSION':'BREAK SESSION';$('done').textContent=`Completed focus sessions: ${state.completed}`;$('mode').textContent=state.mode==='focus'?'Switch to break':'Switch to focus';$('begin').textContent=state.active?'Running':state.remaining<state.duration?'Resume':'Start';$('begin').disabled=state.active;$('pause').disabled=!state.active;$('timerstate').textContent=state.active?'Running: keep this tab open for the completion message':state.remaining<state.duration?'Paused':'Ready to begin';$('timerprogress').style.width=`${clamp((1-state.remaining/state.duration)*100,0,100)}%`;}
  function switchMode(mode){state.mode=mode;state.active=false;state.endAt=null;state.duration=state.remaining=Number($(mode).value)*60000;state[mode]=Number($(mode).value);save();update();}
  function tick(){if(!state.active)return;state.remaining=Math.max(0,state.endAt-Date.now());if(state.remaining<=0){const was=state.mode;state.active=false;state.endAt=null;if(was==='focus')state.completed++;switchMode(was==='focus'?'break':'focus');toast(was==='focus'?'Focus complete: break time!':'Break complete: ready to focus!');text(was==='focus'?'Focus session completed and saved.':'Break completed.');}else{update();}}
  $('begin').addEventListener('click',()=>{tick();if(state.active)return;state.duration=Math.max(state.duration,1);state.endAt=Date.now()+state.remaining;state.active=true;save();update()});
  $('pause').addEventListener('click',()=>{tick();if(!state.active)return;state.remaining=Math.max(0,state.endAt-Date.now());state.active=false;state.endAt=null;save();update()});
  // BM: Event click: kendalikan interaksi tanpa mengubah sumber data atau memintas validasi modul.
  // EN: click event: handle interaction without mutating source data or bypassing module validation.
  $('reset').addEventListener('click',()=>switchMode(state.mode));$('mode').addEventListener('click',()=>switchMode(state.mode==='focus'?'break':'focus'));
  for(const name of ['focus','break'])$(name).addEventListener('change',()=>{const value=clamp(Number($(name).value)||1,name==='focus'?1:1,name==='focus'?180:60);$(name).value=value;state[name]=value;if(!state.active&&state.mode===name){state.duration=state.remaining=value*60000;}save();update()});
  $('clearstats').addEventListener('click',()=>{state.completed=0;save();update();text('Completed session count cleared on this device.')});
  document.addEventListener('visibilitychange',tick);window.addEventListener('focus',tick);const interval=setInterval(tick,500);
  window.addEventListener('pagehide',()=>{clearInterval(interval);document.removeEventListener('visibilitychange',tick)});
  tick();save();update();
}

// BM: randomIndex: Mengasingkan satu langkah operasi supaya boleh disemak dan diuji. Tujuan modul: memasang alat browser mengikut ID, mengurus input dan output setempat, serta mengelakkan muat naik tersirat. Input: max.
// EN: randomIndex: Isolates one operation so it can be reviewed and tested. Module purpose: mounts browser tools by ID, handles local inputs and outputs, and avoids implicit uploads. Inputs: max.
function randomIndex(max){if(max<=0)throw Error('Empty character set.');const limit=Math.floor(0x100000000/max)*max;const a=new Uint32Array(1);do{crypto.getRandomValues(a)}while(a[0]>=limit);return a[0]%max}
function registerPassword(){
  set(`<div class="field-grid">${number('Password length','length',20,8,80)}<div class="field"><span>Allowed characters</span><div class="checkrow"><input type="checkbox" id="upper" checked/><label for="upper">Uppercase letters</label></div><div class="checkrow"><input type="checkbox" id="lower" checked/><label for="lower">Lowercase letters</label></div><div class="checkrow"><input type="checkbox" id="numbers" checked/><label for="numbers">Numbers</label></div><div class="checkrow"><input type="checkbox" id="symbols" checked/><label for="symbols">Symbols</label></div></div></div>${buttons('Generate password','Copy password')}<div class="field" style="margin-top:14px"><label for="password">Generated password</label><input id="password" type="text" autocomplete="off" readonly/></div>${result()}`);
  onRun(()=>{const sets=[['upper','ABCDEFGHIJKLMNOPQRSTUVWXYZ'],['lower','abcdefghijklmnopqrstuvwxyz'],['numbers','0123456789'],['symbols','!@#$%&*()-_=+?']].filter(([id])=>$(id).checked).map(x=>x[1]);if(!sets.length)throw Error('Select at least one character type.');if(n('length')<sets.length)throw Error('Length is too short for chosen sets.');const chars=sets.map(s=>s[randomIndex(s.length)]),all=sets.join('');while(chars.length<n('length'))chars.push(all[randomIndex(all.length)]);for(let i=chars.length-1;i>0;i--){const j=randomIndex(i+1);[chars[i],chars[j]]=[chars[j],chars[i]]}$('password').value=chars.join('');text('Cryptographically random password generated locally. Nothing is stored or sent.')});
  $('secondary').addEventListener('click',async()=>{if(!v('password'))return toast('Generate a password first.');try{await navigator.clipboard.writeText(v('password'));toast('Password copied to clipboard.')}catch{const el=$('password');el.select();document.execCommand('copy');toast('Password selected for copying.')}});
}
// BM: registerUtm: Mengubah state yang berkaitan hanya selepas input dan syarat akses diperiksa. Tujuan modul: memasang alat browser mengikut ID, mengurus input dan output setempat, serta mengelakkan muat naik tersirat.
// EN: registerUtm: Mutates relevant state only after input and access conditions are verified. Module purpose: mounts browser tools by ID, handles local inputs and outputs, and avoids implicit uploads.
function registerUtm(){
  set(`<div class="field-grid">${input('Destination URL','url','https://example.com')}${input('Campaign source (utm_source)','source','newsletter')}${input('Campaign medium (utm_medium)','medium','email')}${input('Campaign name (utm_campaign)','campaign','launch')}${input('Campaign term (optional)','term','')}${input('Campaign content (optional)','content','')}</div>${buttons('Build URL','Copy URL')}<div class="field" style="margin-top:17px"><label for="utmout">Tracking URL</label><textarea id="utmout" rows="4" class="bigoutput" readonly></textarea></div>${result()}`);
  onRun(()=>{let url;try{url=new URL(v('url'))}catch{throw Error('Enter a valid URL including https://')}if(!['http:','https:'].includes(url.protocol))throw Error('Only HTTP(S) URLs are supported.');for(const field of ['source','medium','campaign','term','content']){const name='utm_'+field,content=v(field).trim();if(content)url.searchParams.set(name,content);else url.searchParams.delete(name)}if(!v('source').trim()||!v('medium').trim()||!v('campaign').trim())throw Error('Source, medium and campaign name are required.');$('utmout').value=url.toString();text('UTM tracking URL built. Review destination before sharing.')});
  $('secondary').addEventListener('click',async()=>{if(!v('utmout'))return toast('Build a URL first.');try{await navigator.clipboard.writeText(v('utmout'));toast('URL copied.')}catch{const el=$('utmout');el.select();document.execCommand('copy')}});
}

// BM: makeTile: Menghasilkan representasi yang diperlukan tanpa mengubah input asal secara tidak sengaja. Tujuan modul: memasang alat browser mengikut ID, mengurus input dan output setempat, serta mengelakkan muat naik tersirat. Input: row,href,mark='✦'.
// EN: makeTile: Produces the required representation without unintentionally mutating the input. Module purpose: mounts browser tools by ID, handles local inputs and outputs, and avoids implicit uploads. Inputs: row,href,mark='✦'.
function makeTile(row,href,mark='✦'){
  const [id,title,description]=row;
  const a=document.createElement('a');a.className='tool-card';a.href=href;
  const tile=document.createElement('div');tile.className='mark';tile.textContent=mark;
  const name=document.createElement('h3');name.textContent=title;
  const p=document.createElement('p');p.textContent=description;
  const small=document.createElement('small');small.textContent='Open tool →';
  a.append(tile,name,p,small);return a;
}
// BM: workspace: Mengasingkan satu langkah operasi supaya boleh disemak dan diuji. Tujuan modul: memasang alat browser mengikut ID, mengurus input dan output setempat, serta mengelakkan muat naik tersirat.
// EN: workspace: Isolates one operation so it can be reviewed and tested. Module purpose: mounts browser tools by ID, handles local inputs and outputs, and avoids implicit uploads.
function workspace(){
  const grid=$('group-grid');
  for(const g of groups){
    const count=g.sections.flatMap(section=>section.tools).length;
    const card=makeTile([g.slug,'Zrain '+g.title,g.description],`./${g.slug}/index.html`,g.symbol);
    card.classList.add('group-card');
    const countTag=document.createElement('span');countTag.className='tool-count';countTag.textContent=`${count} tools in one workspace`;
    card.insertBefore(countTag,card.lastChild);
    grid.append(card);
  }
}
// BM: groupDirectory: Mengasingkan satu langkah operasi supaya boleh disemak dan diuji. Tujuan modul: memasang alat browser mengikut ID, mengurus input dan output setempat, serta mengelakkan muat naik tersirat.
// EN: groupDirectory: Isolates one operation so it can be reviewed and tested. Module purpose: mounts browser tools by ID, handles local inputs and outputs, and avoids implicit uploads.
function groupDirectory(){
  if(!group)return;
  const anchor=$('section-nav'),container=$('group-sections');
  for(const [i,section] of group.sections.entries()){
    const id=`section-${i+1}`;
    const jump=document.createElement('a');jump.href=`#${id}`;jump.textContent=section.title;anchor.append(jump);
    const sec=document.createElement('section');sec.className='category-section';sec.id=id;
    const heading=document.createElement('div');heading.className='category-section-heading';
    const copy=document.createElement('div');const h=document.createElement('h3');h.textContent=section.title;
    const description=document.createElement('p');description.textContent=section.description;
    copy.append(h,description);
    const count=document.createElement('span');count.className='section-count';count.textContent=`${section.tools.length} tools`;
    heading.append(copy,count);
    const grid=document.createElement('div');grid.className='tool-grid';
    for(const slug of section.tools){
      const row=catalog.find(item=>item[0]===slug);
      grid.append(makeTile(row,`./${slug}/index.html`,group.symbol));
    }
    sec.append(heading,grid);container.append(sec);
  }
}
if(view==='workspace')workspace();
else if(view==='group')groupDirectory();
else {
  const switcher=$('tool-switcher');
  // BM: Event change: kendalikan interaksi tanpa mengubah sumber data atau memintas validasi modul.
  // EN: change event: handle interaction without mutating source data or bypassing module validation.
  if(switcher)switcher.addEventListener('change',()=>{window.location.href=`../${encodeURIComponent(switcher.value)}/index.html`;});
  if(slug==='color-inspector')registerColor();else if(slug==='compare')registerCompare();else if(slug==='image-compare')registerImageCompare();else if(slug==='file-converter')registerFileConverter();else if(slug==='pdf-editor')registerPdfEditor();else if(slug==='pdf-watermark')registerPdfWatermark();else if(slug==='pdf-organizer')registerPdfOrganizer();else if(slug==='text-extractor')registerOcr();else if(slug==='json-studio')registerJson();else if(slug==='csv-cleaner')registerCsv();else if(slug==='invoice-generator')registerInvoice();else if(slug==='markdown-editor')registerMarkdown();else if(slug==='qr-generator')registerQR();else if(slug==='text-tools')registerTextTools();else if(slug==='focus-timer')registerFocus();else if(slug==='password-generator')registerPassword();else if(slug==='utm-builder')registerUtm();else if(!mountExtendedTool(slug,{set,file,number,select,input,textarea,buttons,preview,result,onRun,chosen,v,n,text,download,downloadText,pdfLib,openPdf,renderPdfPage,zipLib,canvas,imgFile,blobOf,renderImage,safeStem,bytes,$}))registerImageSimple();
}

// Search, quick starts and favourites remain separate from processing engines.
mountDiscovery({view,groupSlug:group?.slug||'',slug});
